        var startTime = null;
        function step(now) {
          if (!startTime) startTime = now;
          var p = Math.min((now - startTime) / 1000, 1);
          var val = Math.ceil(end * p);
          target.textContent = val <= 0 ? "0" : (val >= 1e9 ? val.toExponential(2) : val.toLocaleString());
          if (p < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
