      window.formatNumberInput = function (input) {
        var cursor = input.selectionStart;
        var raw = input.value.replace(/,/g, "");
        if (!isNaN(raw) && raw !== "") {
          var parts = raw.split(".");
          parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
          input.value = parts.join(".");
          var newCursor = cursor + (input.value.length - raw.length);
          input.setSelectionRange(newCursor, newCursor);
        }
      };

      window.filterNumericInput = function (input) {
        input.value = input.value.replace(/[^0-9.]/g, "");
        var parts = input.value.split(".");
        if (parts.length > 2) input.value = parts[0] + "." + parts[1];
        if (input.value.length > 1 && input.value.startsWith("0") && input.value[1] !== ".") {
          input.value = input.value.replace(/^0+/, "");
        }
